// Summarization Strategy — pseudocode
async function buildMessages(history, newUserMessage) {
  const TOKEN_LIMIT = 6000;

  if (countTokens(history) > TOKEN_LIMIT) {
    const oldMessages = history.slice(0, -6); // keep last 3 turns safe
    const recentMessages = history.slice(-6);

    // Ask the LLM to summarize the old part
    const summary = await llm.complete([
      { role: "user", content: `Summarize this conversation:\n${JSON.stringify(oldMessages)}` }
    ]);

    // Replace old messages with a single summary message
    history = [
      { role: "system", content: `Conversation so far: ${summary}` },
      ...recentMessages
    ];
  }

  return [...history, { role: "user", content: newUserMessage }];
}

