// Summarization Strategy
async function summarizeOldMessages(oldMessages, llmClient) {
  const transcript = oldMessages
    .map(m => `${m.role}: ${m.content}`)
    .join("\n");

  const summary = await llmClient.complete({
    messages: [
      { role: "system", content: "Summarize this conversation concisely, preserving key facts and decisions." },
      { role: "user", content: transcript }
    ]
  });

  return { role: "system", content: `[Conversation so far]: ${summary}` };
}

